class Solution {
public:
    int minimumDeviation(vector<int>& nums) {
        priority_queue<int> pq;
        int minVal = INT_MAX;
        for (int x : nums) {
            if (x & 1) x <<= 1;
            pq.push(x);
            if (x < minVal) minVal = x;
        }
        int ans = INT_MAX;
        while (true) {
            int mx = pq.top();
            pq.pop();
            if (mx - minVal < ans) ans = mx - minVal;
            if (mx & 1) break;
            mx >>= 1;
            if (mx < minVal) minVal = mx;
            pq.push(mx);
        }
        return ans;
    }
};
